#include <SoftwareSerial.h>
#include <Wire.h>
#include <LiquidCrystal_I2C.h>

SoftwareSerial bt(10, 11); // RX, TX
LiquidCrystal_I2C lcd(0x27, 16, 2);

void setup() {
  Serial.begin(9600);
  bt.begin(9600);
  lcd.init();
  lcd.backlight();
  lcd.print("Bluetooth Ready!");
}

void loop() {
  if (bt.available()) {
    char c = bt.read();
    lcd.clear();
    lcd.setCursor(0, 0);
    lcd.print("Cmd Received:");
    lcd.setCursor(0, 1);
    lcd.print(c);
    bt.print("ACK: "); bt.println(c);
  }
  int pot = analogRead(A0);
  static unsigned long lastSend = 0;
  if (millis() - lastSend > 1000) {
    bt.print("Telemetry Pot="); bt.println(pot);
    lastSend = millis();
  }
}
